/* @lc app=leetcode id=2246 lang=kotlin */ class Solution { fun longestPath(parent: IntArray, s: String): Int = parent.size.let { n -> parent.indices.groupBy { parent[it] }.let { g -> generateSequence(listOf(0)) { f -> f.flatMap { g[it].orEmpty() }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> IntArray(n).let { down -> order.fold(1) { best, v -> g[v].orEmpty().filter { s[it] != s[v] }.map { down[it] }.sortedDescending().take(2).let { t -> (1 + t.sum()).also { down[v] = 1 + (t.firstOrNull() ?: 0) }.let { maxOf(best, it) } } } } } } } }